@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=1058  cases=60
@exercises configManager (h.cm), arrangeManager (am), commandManager (h.cmgr), arrangeView (av)
@surface   cm:set, am:resizeTake, am:tracksTakes, cmgr:push, av:cursorRow, av:cursorCol, av:setCursor, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, av:setBeatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, av:focus, av:setFocus, cmgr:invoke, av:tracksTakes, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, am:loopRangeQN, am:editCursorQN, am:trimHead, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-36
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 38-40
  @fn mkTrimmable(harness)  @ 44-51
      -- One four-row take at rows 2..5, with four rows of source left over: enough
      -- room for the head to walk in and for the tail to grow.

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 72-80
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 84-90
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 94-101
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 105-113
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 117-127
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 131-142
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 146-155
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 159-170
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 174-182
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 186-194
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 198-207
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 211-223
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 227-241
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 245-254
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 258-274
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 278-294
  @case 'a held selection wins over the cursor take'  [harness]  @ 298-317
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 321-337
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 341-354
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 358-369
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 373-387
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 391-403
  @case 'a bare cursor move clears the selection'  [harness]  @ 407-417
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 421-431
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 435-453
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 457-468
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 472-486
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 490-503
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 507-518
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 522-533
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 537-554
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 558-576
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 580-591
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 595-605
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 609-623
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 627-644
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 648-663
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 667-680
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 684-695
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 699-713
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 717-730
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 734-750
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 754-767
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 771-789
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 795-811
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 815-832
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 836-848
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 852-867
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 871-883
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 889-902
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 906-919
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 923-937
  @case 'the caret on a start row moves the head down, holding the end still'  [harness]  @ 944-953
  @case 'the caret off the start row moves the tail, leaving the head alone'  [harness]  @ 957-966
  @case 'Up on the start row hands back a row of head, taking the caret with it'  [harness]  @ 970-980
  @case 'a head at the origin refuses to grow, and the caret holds'  [harness]  @ 984-993
  @case 'a head trim is floored at one rendered row'  [harness]  @ 997-1007
  @case 'a tail shrink never parks the caret on the head row'  [harness]  @ 1011-1024
  @case 'the armed edge is decided once, from the take the caret stands on'  [harness]  @ 1028-1043
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 1047-1056

